def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    pizza_patches = image_patch.find("pizza")
    table_patches = image_patch.find("table")

    if not pizza_patches or not table_patches:
        return image_patch

    pizza_centers = [(p.left + p.right) / 2, (p.lower + p.upper) / 2 for p in pizza_patches]
    table_centers = [(t.left + t.right) / 2, (t.lower + t.upper) / 2 for t in table_patches]

    pizza_on_table = []
    for i, pizza_center in enumerate(pizza_centers):
        for j, table_center in enumerate(table_centers):
            if abs(pizza_center[0] - table_center[0]) < abs(pizza_center[1] - table_center[1]):
                pizza_on_table.append((i, j))

    if not pizza_on_table:
        return image_patch

    pizza_half_served = [pizza_patches[i] for i, _ in pizza_on_table if pizza_patches[i].simple_query("Is the pizza half served?") == "yes"]

    if not pizza_half_served:
        return image_patch

    return pizza_half_served[0]

